import { Keypair, Operation, TransactionBuilder, Horizon, Asset, Networks } from "@stellar/stellar-sdk";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import Anthropic from "@anthropic-ai/sdk";
const server = new McpServer({ name: "agent", version: "1.0.0" });
const horizon = new Horizon.Server("https://horizon-testnet.stellar.org");
const kp = Keypair.fromSecret(process.env.AGENT_SECRET!);
const anthropic = new Anthropic();
server.tool("send_payment", "Send XLM", { to: z.string(), amount: z.string() }, async ({ to, amount }) => {
  const account = await horizon.loadAccount(kp.publicKey());
  const tx = new TransactionBuilder(account, { fee: "100", networkPassphrase: Networks.TESTNET })
    .addOperation(Operation.payment({ destination: to, asset: Asset.native(), amount }))
    .setTimeout(30).build();
  tx.sign(kp);
  const res = await horizon.submitTransaction(tx);
  return { content: [{ type: "text", text: res.hash }] };
});
export async function onPayment(record: any) {
  const tx = await record.transaction();
  await anthropic.messages.create({ model: "claude-sonnet-5-5", max_tokens: 500,
    messages: [{ role: "user", content: `Handle this customer request: ${tx.memo}` }] });
}
horizon.payments().forAccount(kp.publicKey()).stream({ onmessage: onPayment });

