import { Keypair, Contract, TransactionBuilder, rpc, Address, nativeToScVal, authorizeEntry, Networks } from "@stellar/stellar-sdk";
const kp = Keypair.fromSecret(process.env.PAYER_SECRET!);
const server = new rpc.Server("https://soroban-testnet.stellar.org");
export async function payFor(url: string) {
  const first = await fetch(url);
  const challenge = await first.json();
  const op = new Contract(challenge.asset).call("transfer", new Address(kp.publicKey()).toScVal(),
    new Address(challenge.payTo).toScVal(), nativeToScVal(challenge.amount, { type: "i128" }));
  const tx = new TransactionBuilder(await server.getAccount(kp.publicKey()), { fee: "100", networkPassphrase: Networks.TESTNET })
    .addOperation(op).setTimeout(60).build();
  const sim = await server.simulateTransaction(tx);
  const ledger = (await server.getLatestLedger()).sequence + 12;
  const signed = await Promise.all(sim.result.auth.map((entry) => authorizeEntry(entry, kp, ledger, Networks.TESTNET)));
  return fetch(url, { headers: { "X-PAYMENT": JSON.stringify(signed.map((e) => e.toXDR("base64"))) } });
}

