  const tx = TransactionBuilder.fromXDR(xdr, Networks.TESTNET);
  if (!tx.operations.every((op: any) => op.type === "payment" && ALLOWLIST.has(op.destination) && Number(op.amount) <= 100)) {
    throw new Error("transaction contains operations outside the payroll policy");
  }
  tx.sign(kp);
  return { content: [{ type: "text", text: tx.toXDR() }] };
});

