import { signTransaction } from "@stellar/freighter-api";
import { Operation, TransactionBuilder, Horizon, Asset, Networks } from "@stellar/stellar-sdk";
const horizon = new Horizon.Server("https://horizon-testnet.stellar.org");
export async function pay(from: string, to: string, amount: string) {
  const account = await horizon.loadAccount(from);
  const tx = new TransactionBuilder(account, { fee: "100", networkPassphrase: Networks.TESTNET })
    .addOperation(Operation.payment({ destination: to, asset: Asset.native(), amount })).setTimeout(120).build();
  const { signedTxXdr } = await signTransaction(tx.toXDR(), { networkPassphrase: Networks.TESTNET });
  return horizon.submitTransaction(TransactionBuilder.fromXDR(signedTxXdr, Networks.TESTNET));
}
